#!/usr/bin/env python3
"""Offline, checksum-gated NASA POWER climate analysis."""
from __future__ import annotations
import argparse, hashlib, json, platform, sys
from datetime import datetime,timezone
from pathlib import Path
import geopandas as gpd, matplotlib.pyplot as plt, numpy as np, pandas as pd
from scipy import stats
ROOT=Path(__file__).resolve().parents[3]; A6=ROOT/'data/assignment-06'; S=A6/'source'; O=A6/'output'; T=O/'tables'; V=O/'visualizations'; D=O/'dashboard_assets'
P=['T2M','T2M_MAX','T2M_MIN','PRECTOTCORR','RH2M','ALLSKY_SFC_SW_DWN']; MAP=dict(zip(P,['t2m_mean_C','t2m_max_C','t2m_min_C','precipitation_mm','relative_humidity_pct','solar_radiation_kWh_m2_day']))
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p,x): p.write_text(json.dumps(x,indent=2,default=str)+"\n")
def spell(s):
 m=0;n=0
 for v in s:
  n=n+1 if pd.notna(v) and v<1 else 0;m=max(m,n)
 return m
def main():
 m=json.loads((S/'source_manifest.json').read_text()); assert m['status']=='success' and m['no_synthetic_fallback']
 raw=S/'nasa_power_daily_raw.json'; assert sha(raw)==m['raw_response']['sha256']
 for p,h in m['authoritative_inputs'].items(): assert sha(ROOT/p)==h
 j=json.loads(raw.read_text()); vals=j['properties']['parameter']; assert set(vals)==set(P)
 dates=pd.date_range('1991-01-01','2025-12-31'); assert len(dates)==12784
 units={k:j.get('parameters',{}).get(k,{}).get('units','undocumented') for k in P}; fills={k:j.get('parameters',{}).get(k,{}).get('fill_value',-999) for k in P}
 df=pd.DataFrame(index=dates)
 quality=[]
 for k in P:
  x=pd.Series(vals[k],dtype=float); x.index=pd.to_datetime(x.index,format='%Y%m%d'); assert x.index.is_unique and x.index.is_monotonic_increasing and x.index.equals(dates)
  x=x.replace([fills[k],-999],np.nan); df[MAP[k]]=x
  q=x.dropna(); quality.append({'parameter':k,'expected_record_count':12784,'observed_record_count':len(x),'valid_record_count':len(q),'missing_record_count':x.isna().sum(),'missing_percentage':x.isna().mean()*100,'minimum':q.min(),'maximum':q.max(),'mean':q.mean(),'median':q.median(),'units':units[k],'fill_value':fills[k],'first_valid_date':q.index.min().date(),'last_valid_date':q.index.max().date()})
 if not df.t2m_mean_C.between(-60,60).all() or not df.precipitation_mm.dropna().between(0,1000).all() or not df.relative_humidity_pct.dropna().between(0,100).all(): raise ValueError('grossly impossible weather value')
 df.insert(0,'date',dates); df['year']=dates.year;df['month']=dates.month;df['month_name']=dates.month_name().str[:3];df['day_of_year']=dates.dayofyear
 df['diurnal_temperature_range_C']=df.t2m_max_C-df.t2m_min_C; weather=list(MAP.values());df['is_complete_weather_day']=df[weather].notna().all(axis=1);df['hot_day_ge_35C']=df.t2m_max_C.ge(35);df['frost_day_le_0C']=df.t2m_min_C.le(0);df['dry_day_lt_1mm']=df.precipitation_mm.lt(1);df['heavy_rain_day_ge_25mm']=df.precipitation_mm.ge(25)
 cols=['date','year','month','month_name','day_of_year','t2m_mean_C','t2m_max_C','t2m_min_C','diurnal_temperature_range_C','precipitation_mm','relative_humidity_pct','solar_radiation_kWh_m2_day','is_complete_weather_day','hot_day_ge_35C','frost_day_le_0C','dry_day_lt_1mm','heavy_rain_day_ge_25mm']; df[cols].to_csv(T/'weather_daily_1991_2025.csv',index=False)
 pd.DataFrame(quality).to_csv(T/'weather_data_quality.csv',index=False)
 req=m['request']; loc=json.loads((S/'field_location_summary.json').read_text()); rc=req['returned_grid_coordinates']; rq=req['requested_coordinates']; grid_km=111*np.hypot(rc['latitude']-rq['latitude'],(rc['longitude']-rq['longitude'])*np.cos(np.deg2rad(rq['latitude'])))
 qj={'parameters':quality,'duplicate_dates':0,'missing_dates':0,'incomplete_days':int((~df.is_complete_weather_day).sum()),'requested_coordinates':rq,'returned_coordinates':rc,'requested_to_grid_distance_km':grid_km,'returned_point_within_cluster_extent':loc['cluster_extent']['west']<=rc['longitude']<=loc['cluster_extent']['east'] and loc['cluster_extent']['south']<=rc['latitude']<=loc['cluster_extent']['north'],'all_25_centroids_use_same_analysis_point':True};dump(O/'weather_data_quality.json',qj)
 def agg(g,expected):
  valid=g.is_complete_weather_day.sum(); complete=valid/expected>=.9
  out={'expected_days':expected,'valid_days':valid,'completeness_pct':100*valid/expected,'is_complete_period':complete,'mean_temperature_C':g.t2m_mean_C.mean(),'mean_max_temperature_C':g.t2m_max_C.mean(),'mean_min_temperature_C':g.t2m_min_C.mean(),'mean_diurnal_range_C':g.diurnal_temperature_range_C.mean(),'precipitation_mm':g.precipitation_mm.sum(min_count=1),'mean_relative_humidity_pct':g.relative_humidity_pct.mean(),'mean_solar_radiation_kWh_m2_day':g.solar_radiation_kWh_m2_day.mean(),'hot_day_count':g.hot_day_ge_35C.sum(),'frost_day_count':g.frost_day_le_0C.sum(),'dry_day_count':g.dry_day_lt_1mm.sum(),'heavy_rain_day_count':g.heavy_rain_day_ge_25mm.sum(),'longest_dry_spell_days':spell(g.precipitation_mm)}
  if not complete:
   for k in list(out)[4:]: out[k]=np.nan
  return pd.Series(out)
 monthly=df.groupby(['year','month']).apply(lambda g:agg(g,len(g)),include_groups=False).reset_index();monthly.to_csv(T/'weather_monthly_1991_2025.csv',index=False)
 annual=df.groupby('year').apply(lambda g:agg(g,len(g)),include_groups=False).reset_index().rename(columns={'mean_temperature_C':'annual_mean_temperature_C','precipitation_mm':'annual_precipitation_mm'});annual.to_csv(T/'weather_annual_1991_2025.csv',index=False)
 warm=df[df.month.between(4,10)].groupby('year').apply(lambda g:agg(g,len(g)),include_groups=False).reset_index().rename(columns={'mean_temperature_C':'warm_season_mean_temperature_C','precipitation_mm':'warm_season_precipitation_mm','longest_dry_spell_days':'warm_season_longest_dry_spell_days','hot_day_count':'warm_season_hot_day_count'});warm.to_csv(T/'weather_warm_season_1991_2025.csv',index=False)
 b=monthly[monthly.year<=2020]; normals=b.groupby('month').agg(mean_t2m_C=('mean_temperature_C','mean'),mean_t2m_max_C=('mean_max_temperature_C','mean'),mean_t2m_min_C=('mean_min_temperature_C','mean'),t2m_p10_C=('mean_temperature_C',lambda x:x.quantile(.1)),t2m_p90_C=('mean_temperature_C',lambda x:x.quantile(.9)),mean_monthly_precipitation_mm=('precipitation_mm','mean'),median_monthly_precipitation_mm=('precipitation_mm','median'),precipitation_p10_mm=('precipitation_mm',lambda x:x.quantile(.1)),precipitation_p90_mm=('precipitation_mm',lambda x:x.quantile(.9)),mean_relative_humidity_pct=('mean_relative_humidity_pct','mean'),mean_solar_radiation_kWh_m2_day=('mean_solar_radiation_kWh_m2_day','mean'),mean_hot_day_count=('hot_day_count','mean'),mean_dry_day_count=('dry_day_count','mean')).reset_index();normals.to_csv(T/'climate_normals_1991_2020.csv',index=False)
 a=annual.merge(warm,on='year',suffixes=('','_warm')); metrics=['annual_mean_temperature_C','annual_precipitation_mm','warm_season_mean_temperature_C','warm_season_precipitation_mm']; an=pd.DataFrame({'year':a.year})
 for x in metrics:
  mean=a.loc[a.year<=2020,x].mean();sd=a.loc[a.year<=2020,x].std(ddof=1); an[x]=a[x];an[x+'_anomaly']=a[x]-mean;an[x+'_zscore']=(a[x]-mean)/sd;an[x+'_notable']=an[x+'_zscore'].abs()>=2
  if 'precipitation' in x: an[x+'_anomaly_pct']=100*(a[x]-mean)/mean
 an.to_csv(T/'climate_anomalies_1991_2025.csv',index=False);an[an.year>=2021].to_csv(T/'recent_anomalies_2021_2025.csv',index=False)
 trend_metrics=['annual_mean_temperature_C','annual_precipitation_mm','warm_season_mean_temperature_C','warm_season_precipitation_mm','hot_day_count','warm_season_longest_dry_spell_days']; rows=[]
 for x in trend_metrics:
  y=a[x].dropna();xx=a.loc[y.index,'year']; r=stats.linregress(xx,y);ts=stats.theilslopes(y,xx,alpha=.95);kt=stats.kendalltau(xx,y); rows.append({'metric':x,'n_complete_years':len(y),'ols_slope_per_year':r.slope,'ols_slope_per_decade':r.slope*10,'ols_intercept':r.intercept,'pearson_r':r.rvalue,'r_squared':r.rvalue**2,'ols_p_value':r.pvalue,'ols_standard_error':r.stderr,'ols_slope_ci95_low':r.slope-stats.t.ppf(.975,len(y)-2)*r.stderr,'ols_slope_ci95_high':r.slope+stats.t.ppf(.975,len(y)-2)*r.stderr,'theil_sen_slope_per_year':ts.slope,'theil_sen_slope_per_decade':ts.slope*10,'theil_sen_ci95_low':ts.low_slope,'theil_sen_ci95_high':ts.high_slope,'kendall_tau':kt.statistic,'kendall_p_value':kt.pvalue,'alpha':.05,'ols_significant':r.pvalue<.05,'kendall_significant':kt.pvalue<.05})
 tr=pd.DataFrame(rows);tr.to_csv(T/'climate_trend_statistics.csv',index=False)
 make_figs(normals,a,an,tr,loc,rq,rc)
 notable={'warmest':a.nlargest(3,'annual_mean_temperature_C').year.tolist(),'coolest':a.nsmallest(3,'annual_mean_temperature_C').year.tolist(),'wettest':a.nlargest(3,'annual_precipitation_mm').year.tolist(),'driest':a.nsmallest(3,'annual_precipitation_mm').year.tolist(),'most_hot_days':a.nlargest(3,'hot_day_count')[['year','hot_day_count']].to_dict('records'),'longest_warm_dry_spells':a.nlargest(3,'warm_season_longest_dry_spell_days')[['year','warm_season_longest_dry_spell_days']].to_dict('records')}
 primary=list(T.glob('*.csv'))+list(D.glob('*.png')); summary={'status':'complete','generated_utc':datetime.now(timezone.utc).isoformat(),'representative_weather_point':rq,'returned_grid_coordinates':rc,'field_count':25,'field_cluster_extent':loc['cluster_extent'],'maximum_field_centroid_distance_m':loc['distance_m']['maximum'],'source':'NASA POWER','endpoint':m['endpoint'],'request_period':'1991-01-01/2025-12-31','baseline_period':'1991-2020','recent_anomaly_period':'2021-2025','parameter_units':units,'record_counts':{'daily':len(df),'monthly':len(monthly),'annual':len(annual)},'missing_by_parameter':{q['parameter']:int(q['missing_record_count']) for q in quality},'baseline_climate':{'annual_mean_temperature_C':a.loc[a.year<=2020,'annual_mean_temperature_C'].mean(),'annual_precipitation_mm':a.loc[a.year<=2020,'annual_precipitation_mm'].mean()},'recent_anomalies':an[an.year>=2021].to_dict('records'),'trend_statistics':rows,'most_notable_years':notable,'warm_season_risk_metrics':a[['year','warm_season_hot_day_count','warm_season_longest_dry_spell_days']].to_dict('records'),'output_checksums':{str(p.relative_to(ROOT)):sha(p) for p in primary},'no_synthetic_fallback':True,'cautions':['Gridded estimates are not on-site measurements.','Local descriptive trends do not establish causation or global attribution.','Thresholds do not independently demonstrate crop damage.']};dump(O/'climate_summary.json',summary)
 import matplotlib,pandas,geopandas,scipy,shapely,requests,nbformat
 dump(O/'environment.json',{'python':sys.version,'operating_system':platform.platform(),'versions':{'pandas':pandas.__version__,'geopandas':geopandas.__version__,'matplotlib':matplotlib.__version__,'scipy':scipy.__version__,'shapely':shapely.__version__,'requests':requests.__version__,'nbformat':nbformat.__version__},'execution_timestamp_utc':datetime.now(timezone.utc).isoformat()})
 log=['Source validation: checksum-verified authentic NASA POWER response','Period: 1991-01-01 through 2025-12-31',f'Records: {len(df)} daily, {len(monthly)} monthly, {len(annual)} annual',f'Incomplete days: {(~df.is_complete_weather_day).sum()}',f'Baseline temperature: {summary["baseline_climate"]["annual_mean_temperature_C"]:.2f} C',f'Baseline precipitation: {summary["baseline_climate"]["annual_precipitation_mm"]:.1f} mm',f'Notable years: {notable}',f'Generated artifacts: {len(primary)} checksum-tracked outputs','SUCCESS: Assignment 6 real-data weather and climate workflow complete'];(O/'skill_run.log').write_text('\n'.join(log)+'\n')
 print(log[-1])
def save(fig,name,w=2400,h=1800):
 fig.set_size_inches(w/150,h/150);fig.savefig(V/(name+'.png'),dpi=150,bbox_inches='tight');fig.savefig(V/(name+'.svg'),bbox_inches='tight');plt.close(fig)
def make_figs(n,a,an,tr,loc,rq,rc):
 plt.style.use('seaborn-v0_8-whitegrid');g=gpd.read_file(ROOT/'data/assignment-02/fields_EPSG4326.geojson')
 fig,ax=plt.subplots();g.boundary.plot(ax=ax);ax.scatter(rq['longitude'],rq['latitude'],c='red',marker='*',s=250,label='POWER request');ax.scatter(rc['longitude'],rc['latitude'],c='blue',marker='x',s=120,label='returned grid');ax.legend();ax.set_title(f"25-field cluster and representative weather point\nMaximum centroid distance {loc['distance_m']['maximum']/1000:.1f} km | EPSG:4326");ax.annotate('N',(.95,.9),xycoords='axes fraction',ha='center',fontsize=18);save(fig,'01_field_cluster_and_weather_point')
 fig,(x,y)=plt.subplots(2,1);x.fill_between(n.month,n.t2m_p10_C,n.t2m_p90_C,alpha=.2);x.plot(n.month,n.mean_t2m_C,label='Mean');x.plot(n.month,n.mean_t2m_max_C,label='Max');x.plot(n.month,n.mean_t2m_min_C,label='Min');x.set_ylabel('Temperature (°C)');x.legend();y.bar(n.month,n.mean_monthly_precipitation_mm);y.vlines(n.month,n.precipitation_p10_mm,n.precipitation_p90_mm);y.set_ylabel('Monthly precipitation (mm)');y.set_xlabel('Month');fig.suptitle('Seasonal climatology — Baseline: 1991–2020 | NASA POWER');save(fig,'02_monthly_seasonal_climatology')
 row=tr[tr.metric=='annual_mean_temperature_C'].iloc[0];fig,ax=plt.subplots();ax.plot(a.year,a.annual_mean_temperature_C,'o-');xx=a.year;ax.plot(xx,row.ols_intercept+row.ols_slope_per_year*xx,label='OLS');ts=stats.theilslopes(a.annual_mean_temperature_C,xx);ax.plot(xx,ts.intercept+ts.slope*xx,label='Theil–Sen');ax.axhline(a[a.year<=2020].annual_mean_temperature_C.mean(),ls=':');ax.axvspan(2021,2025,alpha=.15);ax.legend();ax.set(ylabel='Annual mean temperature (°C)',title=f"Annual temperature trend | OLS {row.ols_slope_per_decade:.2f} °C/decade (95% CI {row.ols_slope_ci95_low*10:.2f}, {row.ols_slope_ci95_high*10:.2f}); p={row.ols_p_value:.3f}\nLocal descriptive trend; NASA POWER gridded estimates");save(fig,'03_annual_temperature_trend')
 fig,ax=plt.subplots();z=an.annual_precipitation_mm_zscore;v=an.annual_precipitation_mm_anomaly;ax.bar(an.year,v,color=np.where(v>=0,'#277da1','#f3722c'));ax.scatter(an.loc[z.abs()>=2,'year'],v[z.abs()>=2],marker='*',s=150,c='black',label='|z| ≥ 2');ax.axhline(0,c='black');ax.axvspan(2021,2025,alpha=.12);ax.legend();ax.set(ylabel='Annual precipitation anomaly (mm)',title='Annual precipitation anomalies | Baseline: 1991–2020 | NASA POWER');save(fig,'04_annual_precipitation_anomalies')
 fig,axs=plt.subplots(3,1,sharex=True);axs[0].bar(a.year,a.warm_season_hot_day_count);axs[0].set_ylabel('Hot days ≥35°C');axs[1].plot(a.year,a.warm_season_longest_dry_spell_days,'o-');axs[1].set_ylabel('Longest dry spell (days)');axs[2].bar(a.year,a.warm_season_precipitation_mm);axs[2].set_ylabel('Precipitation (mm)');axs[2].set_xlabel('Year');fig.suptitle('April–October warm-season descriptive weather metrics — thresholds do not prove crop damage');save(fig,'05_warm_season_weather_risks')
 fig,axs=plt.subplots(2,2);g.boundary.plot(ax=axs[0,0]);axs[0,0].scatter(rq['longitude'],rq['latitude'],c='red',marker='*');axs[0,0].set_title('25 fields + cluster weather point');axs[0,1].plot(n.month,n.mean_t2m_C);axs[0,1].set_title('1991–2020 monthly temperature');axs[1,0].plot(a.year,a.annual_mean_temperature_C);axs[1,0].set_title('Annual temperature, 1991–2025');axs[1,1].bar(an.year,an.annual_precipitation_mm_anomaly);axs[1,1].axhline(0,c='black');axs[1,1].set_title('Precipitation anomaly');fig.suptitle('Assignment 6: authentic NASA POWER weather and climate\nOne gridded point represents the cluster; no synthetic fallback. Local descriptive analysis.');save(fig,'06_assignment_06_final_panel',2700,2000)
 # exactly two dashboards
 fig,(x,y)=plt.subplots(1,2);x.plot(n.month,n.mean_t2m_C);x.set(title='Monthly temperature',ylabel='°C',xlabel='Month');y.bar(n.month,n.mean_monthly_precipitation_mm);y.set(title='Monthly precipitation',ylabel='mm',xlabel='Month');fig.suptitle(f"Seasonal climate | 25-field SC cluster ({rq['latitude']:.3f}°N, {abs(rq['longitude']):.3f}°W) | NASA POWER | 1991–2020 baseline");fig.set_size_inches(12,6);fig.savefig(D/'dashboard_seasonal_climate.png',dpi=160,bbox_inches='tight');plt.close(fig)
 fig,(x,y)=plt.subplots(1,2);x.plot(a.year,a.annual_mean_temperature_C);x.set(title='Annual mean temperature',ylabel='°C');y.bar(an.year,an.annual_precipitation_mm_anomaly);y.axhline(0,c='black');y.set(title='Annual precipitation anomaly',ylabel='mm');fig.suptitle(f"Climate trends and anomalies | 25-field SC cluster ({rq['latitude']:.3f}°N, {abs(rq['longitude']):.3f}°W) | NASA POWER | baseline 1991–2020");fig.set_size_inches(12,6);fig.savefig(D/'dashboard_climate_trends_anomalies.png',dpi=160,bbox_inches='tight');plt.close(fig)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--offline',action='store_true',required=True);p.parse_args();T.mkdir(parents=True,exist_ok=True);V.mkdir(parents=True,exist_ok=True);D.mkdir(parents=True,exist_ok=True);main()
